#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# db-export: pick an SSH host, pick a database, download a gzipped SQL dump.
#
# Hosts come from ~/.ssh/config and ~/.ssh/known_hosts (recently used first).
# Database passwords are kept in the desktop keyring (secret-tool).
# Dumps go to $DB_EXPORT_DIR (default ~/Downloads/db-exports).

STATE_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/db-export"
USERS_FILE="$STATE_DIR/ssh-users"
OUT_DIR="${DB_EXPORT_DIR:-$HOME/Downloads/db-exports}"

die() { warn "$1"; exit 1; }

# pick "Header" reads entries on stdin and prints the chosen ones (Tab selects many).
pick() { tv --no-preview --no-remote --height 20 --input-header "$1"; }
NEW_HOST="+ new host"

config_hosts() {
  [[ -f ~/.ssh/config ]] || return 0
  awk 'tolower($1) == "host" { for (i = 2; i <= NF; i++) if ($i !~ /[*?!]/) print $i }' ~/.ssh/config
}

list_hosts() {
  cut -d' ' -f1 "$USERS_FILE"
  config_hosts
  if [[ -f ~/.ssh/known_hosts ]]; then
    awk '$1 !~ /^[|@]/ { print $1 }' ~/.ssh/known_hosts | tr , '\n'
  fi
}

# Runs on the server. Args: ACTION ENGINE [DB]. Stdin: user line, password line.
read -r -d '' DB_SCRIPT <<'EOF' || true
set -o pipefail
action=$1 engine=$2 db=${3:-}
IFS= read -r u || true
IFS= read -r p || true
if [ "$engine" = postgres ]; then
  auth=()
  if [ -n "$u" ]; then export PGPASSWORD="$p"; auth=(-h 127.0.0.1 -U "$u"); fi
  case $action in
    list) psql "${auth[@]}" -d postgres -Atc 'select datname from pg_database where not datistemplate order by 1' ;;
    dump) pg_dump "${auth[@]}" --no-owner --no-privileges "$db" | gzip ;;
  esac
else
  client=$(command -v mariadb || command -v mysql)
  dumper=$(command -v mariadb-dump || command -v mysqldump)
  esc() { local s=${1//\\/\\\\}; printf '%s' "${s//\"/\\\"}"; }
  cnf() { printf '[client]\n'; if [ -n "$u" ]; then printf 'user="%s"\npassword="%s"\n' "$(esc "$u")" "$(esc "$p")"; fi; }
  case $action in
    list) "$client" --defaults-extra-file=<(cnf) -N -e 'show databases' ;;
    dump) "$dumper" --defaults-extra-file=<(cnf) --single-transaction --quick --routines --triggers --no-tablespaces "$db" | gzip ;;
  esac
fi
EOF

# Runs on the server. Prints one line per running database server.
read -r -d '' DETECT_SCRIPT <<'EOF' || true
if pgrep -x mariadbd >/dev/null || { pgrep -x mysqld >/dev/null && mysql --version 2>/dev/null | grep -qi mariadb; }; then echo mariadb
elif pgrep -x mysqld >/dev/null; then echo mysql; fi
if pgrep -x postgres >/dev/null; then echo postgres; fi
EOF

# remote SCRIPT [ARGS...] runs SCRIPT with bash on $DEST; stdin is forwarded.
remote() {
  local b64 args=""
  b64=$(printf '%s' "$1" | base64 -w0)
  shift
  (($#)) && args=$(printf ' %q' "$@")
  # shellcheck disable=SC2029 # $b64 and $args are meant to expand locally.
  ssh "${SSH_OPTS[@]}" "$DEST" "bash -c \"\$(echo $b64 | base64 -d)\" db-export$args"
}

run_db() { printf '%s\n%s\n' "$DB_USER" "$DB_PASS" | remote "$DB_SCRIPT" "$1" "$ENGINE" "${@:2}"; }
try_list() { DATABASES=$(run_db list 2>"$ERR_FILE"); }

run_wizard() {

TOTAL_STAGES=5
ENV_FILE=/dev/null # never read defaults from a project .env in the current directory
mkdir -p "$STATE_DIR" "$OUT_DIR"
touch "$USERS_FILE"
ERR_FILE=$(mktemp)
SSH_OPTS=(-o ControlMaster=auto -o "ControlPath=${XDG_RUNTIME_DIR:-/tmp}/db-export-%C" -o ControlPersist=60)
DEST=""
trap 'rm -f "$ERR_FILE"; [[ -z $DEST ]] || ssh "${SSH_OPTS[@]}" -O exit "$DEST" 2>/dev/null' EXIT

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Host"
HOST=$( { list_hosts | grep -vxE 'github\.com|gitlab\.com|bitbucket\.org|ssh\.github\.com' | awk 'NF && !seen[$0]++'
  echo "$NEW_HOST"; } | pick "Host" || true)
if [[ $HOST == "$NEW_HOST" ]]; then
  HOST=""
  ask HOST "Host name or IP:"
fi
[[ -n $HOST ]] || exit 0

SSH_USER=$(awk -v h="$HOST" '$1 == h { print $2; exit }' "$USERS_FILE")
if [[ -z $SSH_USER ]] && ! config_hosts | grep -qxF "$HOST"; then
  ask SSH_USER "SSH user for $HOST [forge]:"
  SSH_USER=${SSH_USER:-forge}
fi
if [[ $HOST =~ ^\[(.+)\]:([0-9]+)$ ]]; then
  DEST="ssh://${SSH_USER:+$SSH_USER@}${BASH_REMATCH[1]}:${BASH_REMATCH[2]}"
else
  DEST="${SSH_USER:+$SSH_USER@}$HOST"
fi
say "Connecting to $DEST ..."
remote true </dev/null || die "cannot connect to $DEST"
if [[ -n $SSH_USER ]]; then
  { printf '%s %s\n' "$HOST" "$SSH_USER"; awk -v h="$HOST" '$1 != h' "$USERS_FILE"; } >"$USERS_FILE.tmp"
  mv "$USERS_FILE.tmp" "$USERS_FILE"
fi

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Database server on $HOST"
mapfile -t engines < <(remote "$DETECT_SCRIPT" </dev/null)
case ${#engines[@]} in
  0) die "no running MySQL, MariaDB or PostgreSQL server found on $HOST" ;;
  1) ENGINE=${engines[0]} ;;
  *) ENGINE=$(printf '%s\n' "${engines[@]}" | pick "Database server" || true) ;;
esac
[[ -n $ENGINE ]] || exit 0
say "Using $ENGINE."

# ── Stage 3 ───────────────────────────────────────────────────────────────
# Try no password (socket / peer auth / ~/.my.cnf), then the keyring, then ask.
stage "$ENGINE credentials"
DB_USER="" DB_PASS=""
if try_list; then
  note "No password needed."
else
  cached=$(secret-tool lookup service db-export host "$HOST" engine "$ENGINE" 2>/dev/null || true)
  if [[ -n $cached ]]; then
    DB_USER=${cached%%:*} DB_PASS=${cached#*:}
  fi
  if [[ -n $cached ]] && try_list; then
    note "Using saved credentials for $DB_USER."
  else
    [[ -z $cached ]] || warn "Saved credentials for $HOST no longer work."
    while :; do
      ask DB_USER "$ENGINE user [forge]:"
      DB_USER=${DB_USER:-forge}
      ask_secret DB_PASS "$ENGINE password for $DB_USER:"
      try_list && break
      warn "Login failed:"
      sed 's/^/    /' "$ERR_FILE"
    done
    printf '%s:%s' "$DB_USER" "$DB_PASS" |
      secret-tool store --label="db-export $ENGINE@$HOST" service db-export host "$HOST" engine "$ENGINE"
    printf '  %s✓ saved%s credentials in the keyring\n' "$GREEN" "$RESET"
  fi
fi

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Databases on $HOST"
mapfile -t selected < <(grep -vxE 'information_schema|performance_schema|mysql|sys|postgres' <<<"$DATABASES" |
  pick 'Database (Tab selects more than one)' || true)
((${#selected[@]})) || exit 0

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Export"
ts=$(date +%Y%m%d-%H%M%S)
status=0
for db in "${selected[@]}"; do
  file="$OUT_DIR/${HOST//[^A-Za-z0-9._-]/_}_${db}_${ts}.sql.gz"
  say "$db ($ENGINE on $HOST)"
  if run_db dump "$db" | pv -b >"$file" && gzip -t "$file"; then
    printf '  %s✓ saved%s %s (%s)\n' "$GREEN" "$RESET" "$file" "$(du -h "$file" | cut -f1)"
  else
    rm -f "$file"
    warn "export of $db failed"
    status=1
  fi
done
exit "$status"
}

run_wizard "$@"; exit
